{
  "returncode": 0,
  "output_head": "======= GAME SHOW =======
<% content_for :title, "#{@quiz.title} · Quizzy" %>
<section class="cover cover--blue cover--calm">
  <div class="screen">
    <div class="screen__top">
      <span class="logo screen__logo"><span class="logo__mark">?</span>Quizzy</span>
      <span><%= @quiz.title %></span>
    </div>
    <div class="screen__body">
      <% if @game.lobby? %>
        <div class="lobby">
          <div>
            <h1 class="lobby__title"><%= @quiz.title %></h1>
            <p class="lobby__join">Join at</p>
            <p class="lobby__url"><%= @join_url %></p>
            <div class="counter-pill"
                 data-controller="live"
                 data-live-mode-value="text"
                 data-live-url-value="<%= counter_moderate_quiz_game_path(@quiz, @game) %>"
                 data-live-signature-value="<%= @counter_text %>"
                 data-live-code-value="<%= @game.code %>"
                 data-live-phase-value="<%= @game.phase %>"
                 data-live-interval-value="500"
                 aria-live="polite"><%= @counter_text %></div>
          </div>
          <div class="qr" role="img" aria-label="QR code"><%= @qr_svg %></div>
        </div>
      <% elsif (@game.question? || @game.results?) && @question %>
        <div class="stage-question__num">Question <%= @game.question_number %> of <%= @game.question_total %></div>
        <div class="answers-counter"
             data-controller="live"
             data-live-mode-value="text"
             data-live-url-value="<%= counter_moderate_quiz_game_path(@quiz, @game) %>"
             data-live-signature-value="<%= @counter_text %>"
             data-live-code-value="<%= @game.code %>"
             data-live-phase-value="<%= @game.phase %>"
             data-live-interval-value="500"
             aria-live="polite"><%= @counter_text %></div>
        <div class="stage-question__body"><%= @question.body %></div>
        <ol class="stage-options<%= " stage-options--results" if @game.results? %>">
          <% @question.ordered_options.each_with_index do |option, index| %>
            <% count = @option_counts[option.id].to_i %>
            <% share = @answer_total.to_i.zero? ? 0 : (count * 100.0 / @answer_total).round %>
            <li class="stage-option<%= " is-correct" if @game.results? && option.correct? %>"<% if @game.results? %> style="--share: <%= share %>%"<% end %>>
              <% if @game.results? %>
                <span class="stage-option__bar" aria-hidden="true"></span>
              <% end %>
              <span class="stage-option__letter"><%= option_letter(index) %></span>
              <span class="stage-option__title"><%= option.body %></span>
              <% if @game.results? %>
                <span class="stage-option__count"><%= count %></span>
                <% if option.correct? %>
                  <span class="stage-option__mark">Correct</span>
                <% end %>
              <% end %>
            </li>
          <% end %>
        </ol>
      <% else %>
        <div>
          <p class="screen__kicker"><%= @quiz.title %></p>
          <h1 class="lobby__title">The quiz is over</h1>
        </div>
      <% end %>
    </div>
  </div>
</section>
<div class="screen-controls">
  <div class="screen-controls__info">
    <% if @game.question? || @game.results? %>
      <span class="answers-counter"
            data-controller="live"
            data-live-mode-value="text"
            data-live-url-value="<%= counter_moderate_quiz_game_path(@quiz, @game) %>"
            data-live-signature-value="<%= @counter_text %>"
            data-live-code-value="<%= @game.code %>"
            data-live-phase-value="<%= @game.phase %>"
            data-live-interval-value="500"
            aria-live="polite"><%= @counter_text %></span>
    <% end %>
    <%= link_to "Back to quiz", moderate_quiz_path(@quiz) %>
  </div>
  <div class="buttons">
    <% if @game.lobby? %>
      <%= button_to "Start", start_moderate_quiz_game_path(@quiz, @game), class: "btn btn--pink btn--lg", form: { data: { turbo: false } } %>
    <% elsif @game.question? %>
      <%= button_to "Finish", finish_moderate_quiz_game_path(@quiz, @game), class: "btn btn--pink btn--lg", form: { data: { turbo: false } } %>
    <% elsif @game.results? %>
      <%= button_to (@game.last_question? ? "End quiz" : "Next"), advance_moderate_quiz_game_path(@quiz, @game), class: "btn btn--pink btn--lg", form: { data: { turbo: false } } %>
    <% end %>
  </div>
</div>
======= PLAY SHOW =======
<% content_for :title, "#{@quiz.title} · Quizzy" %>
<div class="play">
  <div class="play__top">
    <span class="logo play__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span><%= @player&.name || @quiz.title %></span>
  </div>
  <div class="play__body play__body--top"
       data-controller="live"
       data-live-url-value="<%= live_play_path(@game.code) %>"
       data-live-signature-value="<%= @signature %>"
       data-live-code-value="<%= @game.code %",
  "output_tail": "tatic values = {
    url: String,
    signature: String,
    interval: { type: Number, default: 500 },
    mode: { type: String, default: "html" },
    phase: String,
    code: String
  }

  connect() {
    this.inflight = false
    this.submitting = false
    this.pending = false
    this.delay = this.intervalValue
    this.onSubmit = (event) => this.submit(event)
    this.element.addEventListener("submit", this.onSubmit)
    if (this.signatureValue === "finished") return
    this.onVisible = () => {
      if (!document.hidden) this.nudge()
    }
    document.addEventListener("visibilitychange", this.onVisible)
    this.startTimer()
    this.subscribe()
    this.refresh()
  }

  disconnect() {
    this.stop()
    if (this.onVisible) document.removeEventListener("visibilitychange", this.onVisible)
    this.element.removeEventListener("submit", this.onSubmit)
  }

  subscribe() {
    if (!this.hasCodeValue || !this.codeValue) return
    try {
      this.subscription = cable().subscriptions.create(
        { channel: "GameChannel", code: this.codeValue },
        {
          received: () => this.nudge(),
          connected: () => this.nudge(),
          disconnected: () => this.nudge()
        }
      )
    } catch (_) {
      // Polling still follows the game if the socket cannot connect.
    }
  }

  startTimer() {
    this.stopTimer()
    this.timer = window.setInterval(() => this.refresh(), this.delay || this.intervalValue)
  }

  stopTimer() {
    if (this.timer) window.clearInterval(this.timer)
    this.timer = null
  }

  stop() {
    this.stopTimer()
    if (this.subscription) {
      this.subscription.unsubscribe()
      this.subscription = null
    }
  }

  nudge() {
    this.pending = true
    this.refresh()
  }

  async refresh() {
    if (this.inflight || this.submitting || !this.hasUrlValue || !this.urlValue) return
    this.inflight = true
    this.pending = false
    try {
      const url = new URL(this.urlValue, window.location.href)
      url.searchParams.set("signature", this.signatureValue || "")
      url.searchParams.set("_", Date.now().toString())
      const response = await fetch(url.toString(), {
        method: "GET",
        credentials: "same-origin",
        cache: "no-store",
        headers: {
          Accept: this.modeValue === "text" ? "text/plain" : "text/html",
          "X-Live": "1"
        }
      })
      if (response.status === 204 || !response.ok) {
        if (this.signatureValue === "finished") this.stop()
        return
      }
      const phase = response.headers.get("X-Game-Phase")
      if (this.modeValue === "text" && this.hasPhaseValue && phase && phase !== this.phaseValue) {
        window.location.reload()
        return
      }
      const signature = response.headers.get("X-Live-Signature")
      if (signature && signature === this.signatureValue) return
      const body = await response.text()
      this.apply(body, signature || "")
    } catch (_) {
      // Retry on the next tick. Conference Wi-Fi drops packets.
    } finally {
      this.inflight = false
      if (this.pending && this.timer) this.refresh()
    }
  }

  apply(body, signature) {
    if (this.modeValue === "text") {
      if (body) this.element.textContent = body
    } else {
      const active = document.activeElement
      const typing = active && this.element.contains(active) &&
        (active.tagName === "INPUT" || active.tagName === "TEXTAREA")
      if (typing && signature !== "finished") return
      this.element.innerHTML = body
    }
    if (signature) this.signatureValue = signature
    if (signature === "finished") this.stop()
  }

  async submit(event) {
    const form = event.target
    if (!(form instanceof HTMLFormElement)) return
    if (!form.hasAttribute("data-live-submit")) return
    event.preventDefault()
    if (this.submitting) return
    this.submitting = true
    try {
      const response = await fetch(form.action, {
        method: (form.getAttribute("method") || "post").toUpperCase(),
        body: new FormData(form),
        credentials: "same-origin",
        cache: "no-store",
        headers: { Accept: "text/html", "X-Live": "1" }
      })
      if (response.ok && response.headers.get("X-Live-Partial")) {
        const signature = response.headers.get("X-Live-Signature") || ""
        const body = await response.text()
        this.apply(body, signature)
      } else {
        window.location.reload()
      }
    } catch (_) {
      form.submit()
    } finally {
      this.submitting = false
    }
  }
}
