module ApplicationHelper
  def option_letter(index)
    if index < 26
      ("A".ord + index).chr
    else
      (index + 1).to_s
    end
  end

  def moderator_area?
    controller_path.start_with?("moderate") && !@preview_mode && !@stage_mode
  end

  def join_url_for(game)
    "#{request.base_url}#{play_path(game.code)}"
  end
end
