  "output_head": "/*
 * Quizzy: a live quiz for conference screens.
 * Bright colors for LED walls and projectors, big type, pill buttons.
 */

@font-face {
  font-family: "Inter";
  font-display: swap;
  font-style: normal;
  font-weight: 100 900;
  src: url("Inter-latin.woff2") format("woff2");
}

:root {
  --c-lavender: #e9e6ff;
  --c-blue: #2a12c9;
  --c-pink: #ff2e88;
  --c-night: #0d0640;
  --c-sun: #ffd23f;
  --c-white: #fff;
  --c-success: #00b36b;
  --c-muted: #6f66b8;

  --f-display: "Inter", system-ui, sans-serif;
  --f-text: "Inter", system-ui, -apple-system, sans-serif;

  --radius: 16px;
  --gutter: clamp(16px, 4vw, 60px);
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  background: var(--c-lavender);
  color: var(--c-blue);
  font-family: var(--f-text);
  font-size: 18px;
  line-height: 1.35;
  letter-spacing: -0.01em;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 {
  font-family: var(--f-display);
  font-weight: 900;
  letter-spacing: -0.035em;
  line-height: 1;
  margin: 0 0 0.5em;
}

h1 { font-size: clamp(36px, 6vw, 72px); }
h2 { font-size: clamp(26px, 3.5vw, 44px); }
h3 { font-size: clamp(20px, 2.2vw, 28px); }

p { margin: 0 0 1em; }

a { color: inherit; text-underline-offset: 0.15em; }
a:hover { color: var(--c-pink); }

img, svg { max-width: 100%; }

.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.18em;
  font: 900 32px/1 var(--f-display);
  letter-spacing: -0.05em;
  color: inherit;
  white-space: nowrap;
}
.logo__mark {
  display: inline-grid;
  place-items: center;
  width: 1.05em;
  height: 1.05em;
  border-radius: 50% 50% 50% 12%;
  background: var(--c-sun);
  color: var(--c-night);
  font-size: 0.8em;
  letter-spacing: 0;
}

/* ---------- Buttons ---------- */

.btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4em;
  border: 0;
  border-radius: 1000px;
  background: var(--c-blue);
  color: var(--c-lavender);
  font: 600 18px/1 var(--f-text);
  letter-spacing: -0.01em;
  padding: 0.85em 1.4em;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s, box-shadow 0.15s;
}

.btn:hover {
  background: var(--c-lavender);
  color: var(--c-blue);
  box-shadow: inset 0 0 0 2px var(--c-blue);
}

.btn--pink { background: var(--c-pink); color: var(--c-white); }
.btn--pink:hover { background: var(--c-white); color: var(--c-pink); box-shadow: inset 0 0 0 2px var(--c-pink); }

.btn--ghost { background: transparent; color: var(--c-blue); box-shadow: inset 0 0 0 2px var(--c-blue); }
.btn--ghost:hover { background: var(--c-blue); color: var(--c-lavender); }

.btn--light { background: var(--c-lavender); color: var(--c-blue); }
.btn--light:hover { background: var(--c-blue); color: var(--c-lavender); box-shadow: inset 0 0 0 2px var(--c-lavender); }

.btn--danger { background: transparent; color: var(--c-pink); box-shadow: inset 0 0 0 2px var(--c-pink); }
.btn--danger:hover { background: var(--c-pink); color: var(--c-white); }

.btn--sm { font-size: 15px; padding: 0.6em 1em; }
.btn--lg { font-size: clamp(20px, 2vw, 28px); padding: 0.8em 1.6em; }
.btn--icon { padding: 0.5em 0.7em; font-size: 15px; }

.btn[disabled], .btn--disabled { opacity: 0.4; cursor: not-allowed; pointer-events: none; }

.buttons { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
.buttons form { display: contents; }

/* ---------- Forms ---------- */

.field { display: flex; flex-direction: column; gap: 6px; margin-bottom: 20px; }
.field label { font-weight: 600; font-size: 15px; }
.field-hint { font-size: 14px; color: var(--c-muted); }

.input, textarea.input {
  width: 100%;
  font: 500 18px/1.3 var(--f-text);
  color: var(--c-blue);
  background: var(--c-white);
  border: 2px solid var(--c-blue);
  border-radius: 12px;
  padding: 0.7em 0.9em;
  outline: none;
}

.input:focus { border-color: var(--c-pink); box-shadow: 0 0 0 4px rgb(255 46 136 / 0.18); }
textarea.input { min-height: 110px; resize: vertical; }
.input--number { max-width: 140px; }

input[type="checkbox"] {
  appearance: none;
  width: 26px;
  height: 26px;
  margin: 0;
  flex-shrink: 0;
  border: 2px solid var(--c-blue);
  border-radius: 6px;
  background: var(--c-white) center / 18px no-repeat;
  cursor: pointer;
}

